#!/usr/bin/env python3
"""Consent-management HTTP API over SQLite.

Append-only hash-chained event store served with the Python standard
library only (http.server + sqlite3). The consent_events table is strictly
append-only: nothing in this code ever modifies or removes existing rows.
"""

import hashlib
import json
import os
import re
import sqlite3
import sys
import threading
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlparse

GENESIS = "0" * 64
LOCK = threading.Lock()

DB_ARGS = {"db": None, "port": None}


def get_conn():
    conn = sqlite3.connect(DB_ARGS["db"])
    conn.row_factory = sqlite3.Row
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS consent_events (
            id         INTEGER PRIMARY KEY,
            subject    TEXT NOT NULL,
            purpose    TEXT NOT NULL,
            action     TEXT NOT NULL CHECK (action IN ('grant', 'revoke')),
            ts         TEXT NOT NULL,
            prev_hash  TEXT NOT NULL,
            hash       TEXT NOT NULL
        )
        """
    )
    return conn


def compute_hash(eid, subject, purpose, action, ts, prev_hash):
    payload = "|".join(
        [str(eid), subject, purpose, action, ts, prev_hash]
    )
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def replay(conn, subject, purpose):
    """Return the current action for (subject, purpose): 'grant',
    'revoke', or None if no events exist."""
    row = conn.execute(
        "SELECT action FROM consent_events WHERE subject = ? AND purpose = ? "
        "ORDER BY id DESC LIMIT 1",
        (subject, purpose),
    ).fetchone()
    return row["action"] if row else None


def append_event(conn, subject, purpose, action):
    """Append a new event to the chain. Callers must hold LOCK."""
    row = conn.execute(
        "SELECT id, hash FROM consent_events ORDER BY id DESC LIMIT 1"
    ).fetchone()
    prev_hash = row["hash"] if row else GENESIS
    next_id = (row["id"] + 1) if row else 1
    ts = datetime.now(timezone.utc).isoformat()
    digest = compute_hash(next_id, subject, purpose, action, ts, prev_hash)
    conn.execute(
        "INSERT INTO consent_events (id, subject, purpose, action, ts, prev_hash, hash) "
        "VALUES (?, ?, ?, ?, ?, ?, ?)",
        (next_id, subject, purpose, action, ts, prev_hash, digest),
    )
    conn.commit()
    return {
        "id": next_id,
        "subject": subject,
        "purpose": purpose,
        "action": action,
        "ts": ts,
    }


class Handler(BaseHTTPRequestHandler):
    server_version = "ConsentAPI/1.0"

    def log_message(self, fmt, *args):
        pass

    def _send(self, code, obj):
        data = json.dumps(obj).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_POST(self):
        if self.path.rstrip("/") != "/consent":
            return self._send(404, {"error": "not found"})
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length else b""
        try:
            body = json.loads(raw.decode("utf-8")) if raw else {}
        except (json.JSONDecodeError, UnicodeDecodeError):
            return self._send(400, {"error": "invalid JSON body"})
        if not isinstance(body, dict):
            return self._send(400, {"error": "JSON object expected"})
        subject = body.get("subject")
        purpose = body.get("purpose")
        action = body.get("action")
        if (
            not isinstance(subject, str)
            or not isinstance(purpose, str)
            or action not in ("grant", "revoke")
        ):
            return self._send(
                400,
                {"error": "subject, purpose and action ('grant'|'revoke') are required"},
            )
        with LOCK:
            conn = get_conn()
            try:
                current = replay(conn, subject, purpose)
                if action == "revoke" and current != "grant":
                    return self._send(
                        409,
                        {"error": "revoke requires a prior active grant"},
                    )
                event = append_event(conn, subject, purpose, action)
            finally:
                conn.close()
        return self._send(201, {"ok": True, **event})

    def do_GET(self):
        parsed = urlparse(self.path)

        m = re.fullmatch(r"/consent/([^/]+)/([^/]+)", parsed.path)
        if m:
            subject, purpose = unquote(m.group(1)), unquote(m.group(2))
            with LOCK:
                conn = get_conn()
                try:
                    current = replay(conn, subject, purpose)
                    count = conn.execute(
                        "SELECT COUNT(*) AS c FROM consent_events "
                        "WHERE subject = ? AND purpose = ?",
                        (subject, purpose),
                    ).fetchone()["c"]
                finally:
                    conn.close()
            if count == 0:
                return self._send(
                    404, {"error": "no consent events for this subject/purpose"}
                )
            return self._send(
                200,
                {
                    "subject": subject,
                    "purpose": purpose,
                    "status": current,
                },
            )

        if parsed.path == "/audit/verify":
            with LOCK:
                conn = get_conn()
                try:
                    rows = conn.execute(
                        "SELECT id, subject, purpose, action, ts, prev_hash, hash "
                        "FROM consent_events ORDER BY id"
                    ).fetchall()
                finally:
                    conn.close()
            prev = GENESIS
            for row in rows:
                expected = compute_hash(
                    row["id"],
                    row["subject"],
                    row["purpose"],
                    row["action"],
                    row["ts"],
                    row["prev_hash"],
                )
                if row["prev_hash"] != prev or row["hash"] != expected:
                    return self._send(
                        200,
                        {"ok": False, "bad_id": row["id"], "count": len(rows)},
                    )
                prev = row["hash"]
            return self._send(200, {"ok": True, "count": len(rows)})

        return self._send(404, {"error": "not found"})


def main(argv):
    args = argv[1:]
    db = None
    port = None
    i = 0
    while i < len(args):
        if args[i] == "--db" and i + 1 < len(args):
            db = args[i + 1]
            i += 2
        elif args[i] == "--port" and i + 1 < len(args):
            port = int(args[i + 1])
            i += 2
        else:
            i += 1
    DB_ARGS["db"] = db or os.environ.get("CONSENT_DB", "consent.db")
    DB_ARGS["port"] = port or int(os.environ.get("PORT", "8735"))

    server = ThreadingHTTPServer(("127.0.0.1", DB_ARGS["port"]), Handler)
    print(
        f"consent api listening on 127.0.0.1:{DB_ARGS['port']} db={DB_ARGS['db']}",
        flush=True,
    )
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main(sys.argv)

